    spans.forEach(function(s,i){s.animate&&s.animate([{transform:'translateY(110%) rotate(3deg)'},{transform:'none'}],{duration:1100,delay:150+i*110,easing:'cubic-bezier(.16,1,.3,1)',fill:'backwards'})});
