    if(window.PD_NL_TEST){window.PD_NL_TEST(data,form);return}
    if(N.endpoint){ // il vostro script sull'hosting Aruba: mail grafica da PAN.DOOR.A GROUP + avviso a voi + elenco iscritti
      Promise.race([new Promise(function(_,ko){setTimeout(function(){ko(new Error('timeout'))},9000)}),fetch(N.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nome:nome,cognome:g('Mbiemri'),email:g('email'),telefono:tel,stato:st?st.n:g('Shteti'),provincia:prov,pagina:location.href.split('?')[0],consenso:true,sito_web:(($('[name="sito_web"]',f)||{}).value||'')})})])
        .then(function(r){return r.json()}).then(function(j){if(!j||!j.ok)throw new Error((j&&j.errore)||'errore');nlSuccess(f,nome)})
        .catch(function(){form.submit()});
      return;
    }
    salvaDb.then(function(){form.submit()});
